#!/bin/bash
# Captures Docker's and UFW's state on one OS image as golden files for the
# firewall's Docker integration: the loaded netfilter state, UFW's files and
# the daemon's view of its networks and containers, for each scenario.
#
# Usage: capture.sh <image> <outdir>
#   image is one of ubuntu:22.04, ubuntu:24.04, debian:12, debian:13
#   for example: capture.sh ubuntu:24.04 internal/modules/firewall/dockerfw/testdata/capture
# Writes <outdir>/<image-slug>/<scenario>/ for the scenarios base, block,
# cleanup and routed. Docker's packages are the ones test/harness/images.json
# pins for the image, checked against their hashes. Each scenario runs in a
# privileged container of its own network namespace, which is removed when
# the scenario ends and on exit; the host's firewall is never touched.
#
# commands.txt holds "<exit status><TAB><command>" for every UFW, Docker and
# restore command a scenario runs. For stable output the "# Generated by" and
# "# Completed on" lines of the save output are dropped and chain counters
# are written as [0:0]. A legacy table is captured only when it already
# exists in the container's network namespace (/proc/net/ip*_tables_names):
# asking for another one would make the host kernel load its module.
#
# The single-quoted scripts and the echoed commands run inside the
# container, so their expansions and escapes are meant to happen there.
# shellcheck disable=SC2016,SC2028
set -euo pipefail

# Git Bash rewrites arguments that look like paths for native programs.
# Docker gets its container paths as they are, and a host path given to it
# is converted to Windows form first; every other program keeps the
# rewriting, which its host paths need.
docker() { MSYS_NO_PATHCONV=1 command docker "$@"; }
hostpath() {
	if command -v cygpath >/dev/null; then
		cygpath -m "$1"
	else
		printf '%s' "$1"
	fi
}

if [ $# -ne 2 ] || [ -z "$2" ]; then
	echo "usage: $0 <image> <outdir>" >&2
	exit 2
fi
image=$1
slug=$(printf '%s' "$image" | tr ':/' '--')
outdir=$2

for tool in docker jq curl sha256sum timeout; do
	if ! command -v "$tool" >/dev/null; then
		echo "$0: $tool is required" >&2
		exit 1
	fi
done

root=$(cd "$(dirname "$0")/../../../../../.." && pwd) || exit 1
images=$root/test/harness/images.json
if ! jq -e --arg id "$slug" 'any(.os[]; .id == $id)' "$images" >/dev/null; then
	echo "$0: $image is not an image of $images" >&2
	exit 2
fi

name=
pkgs=$(mktemp -d)
on_exit() {
	if [ -n "$name" ]; then
		docker rm -f "$name" >/dev/null 2>&1 || true
	fi
	rm -rf "$pkgs"
}
trap on_exit EXIT
# apt reads local packages as the _apt user.
chmod 755 "$pkgs"

list=$(jq -r --arg id "$slug" '.os[] | select(.id == $id) | .packages[] | select(.name | IN("docker-ce", "docker-ce-cli", "containerd.io")) | [.url, .sha256] | @tsv' "$images")
while IFS=$'\t' read -r url sum; do
	file=$pkgs/${url##*/}
	curl -fsSL --connect-timeout 15 --max-time 600 --retry 3 -o "$file" "$url"
	printf '%s  %s\n' "$sum" "$file" | sha256sum -c --quiet
done <<<"$list"
MSYS_NO_PATHCONV=1 timeout 900 docker pull -q "$image" >/dev/null

dx() { docker exec "$name" bash -euo pipefail -c "$1"; }

# run_recorded runs a command in the container and appends its exit status
# and text to commands.txt. record aborts the script when the command fails;
# attempt never does, for the commands whose status the tests read.
run_recorded() {
	local status=0 output
	output=$(dx "$1" 2>&1) || status=$?
	printf '%s\t%s\n' "$status" "$1" >>"$dir/commands.txt"
	if [ "$status" -ne 0 ]; then
		printf '%s exited %s:\n%s\n' "$1" "$status" "$output" >&2
	fi
	return "$status"
}
record() { run_recorded "$1" || exit 1; }
attempt() { run_recorded "$1" || true; }

base() {
	record 'ufw --force enable'
	record 'ufw allow 22/tcp'
	dx 'setsid dockerd >/var/log/dockerd.log 2>&1 &'
	for _ in $(seq 1 90); do
		dx 'docker info' >/dev/null 2>&1 && break
		sleep 1
	done
	if ! dx 'docker info' >/dev/null 2>&1; then
		dx 'cat /var/log/dockerd.log' >&2
		echo "$0: dockerd did not start" >&2
		exit 1
	fi
	dx 'timeout 900 docker pull -q busybox:1.37' >/dev/null
	record 'docker run -d --name web -p 8080:80 -p 127.0.0.1:8081:80 busybox:1.37 httpd -f -p 80'
	record 'docker network create -o com.docker.network.bridge.name=dpcustom --subnet 172.30.0.0/24 custom'
	record 'docker run -d --name app --network custom -p 9090:80 busybox:1.37 httpd -f -p 80'
	record 'docker network create --ipv6 --subnet fd00:dead::/64 v6net'
	record 'docker run -d --name six --network v6net -p 8443:80 busybox:1.37 httpd -f -p 80'
}

# block_text prints the spec's Docker block for one family: v4 with the
# binding of web's port 8080/tcp at address $2 under chain dp-b-$3, v6
# without it.
block_text() {
	local fam=$1 addr=$2 id=$3
	echo '# BEGIN DARKPANEL docker'
	echo '*filter'
	if [ "$fam" = v4 ]; then
		echo ':ufw-user-forward - [0:0]'
	else
		echo ':ufw6-user-forward - [0:0]'
	fi
	echo ':DOCKER-USER - [0:0]'
	echo ':darkpanel-docker-bindings - [0:0]'
	echo ':darkpanel-docker-deny - [0:0]'
	if [ "$fam" = v4 ]; then
		echo ":dp-b-$id - [0:0]"
	fi
	echo '-A DOCKER-USER -m conntrack --ctstate RELATED,ESTABLISHED -j RETURN'
	echo '-A DOCKER-USER -i docker0 -j RETURN'
	echo '-A DOCKER-USER -i br-+ -j RETURN'
	echo '-A DOCKER-USER -i dpcustom -j RETURN'
	if [ "$fam" = v4 ]; then
		echo '-A DOCKER-USER -s 10.0.0.0/8 -j RETURN'
		echo '-A DOCKER-USER -s 172.16.0.0/12 -j RETURN'
		echo '-A DOCKER-USER -s 192.168.0.0/16 -j RETURN'
		echo '-A DOCKER-USER -s 100.64.0.0/10 -j RETURN'
	else
		echo '-A DOCKER-USER -s fc00::/7 -j RETURN'
		echo '-A DOCKER-USER -s fe80::/10 -j RETURN'
	fi
	echo '-A DOCKER-USER -m conntrack --ctstate DNAT -j darkpanel-docker-bindings'
	echo '-A DOCKER-USER -o docker0 -j darkpanel-docker-deny'
	echo '-A DOCKER-USER -o br-+ -j darkpanel-docker-deny'
	echo '-A DOCKER-USER -o dpcustom -j darkpanel-docker-deny'
	if [ "$fam" = v4 ]; then
		echo '-A DOCKER-USER -d 10.0.0.0/8 -j darkpanel-docker-deny'
		echo '-A DOCKER-USER -d 172.16.0.0/12 -j darkpanel-docker-deny'
		echo '-A DOCKER-USER -d 192.168.0.0/16 -j darkpanel-docker-deny'
	else
		echo '-A DOCKER-USER -d fc00::/7 -j darkpanel-docker-deny'
	fi
	echo '-A DOCKER-USER -j RETURN'
	if [ "$fam" = v4 ]; then
		echo "-A darkpanel-docker-bindings -p tcp -d $addr --dport 80 -m conntrack --ctorigdstport 8080 -j dp-b-$id"
	fi
	echo '-A darkpanel-docker-bindings -j darkpanel-docker-deny'
	if [ "$fam" = v4 ]; then
		echo "-A dp-b-$id -s 203.0.113.0/24 -j darkpanel-docker-deny"
		echo "-A dp-b-$id -s 0.0.0.0/0 -j ufw-user-forward"
		echo "-A dp-b-$id -j darkpanel-docker-deny"
	fi
	echo '-A darkpanel-docker-deny -m limit --limit 3/min -j LOG --log-prefix "[DARKPANEL DOCKER DENY] "'
	echo '-A darkpanel-docker-deny -j DROP'
	echo 'COMMIT'
	echo '# END DARKPANEL docker'
}

block() {
	local id addr
	id=$(printf '%s' 'web|all|8080|tcp' | sha256sum | cut -c1-12)
	addr=$(dx 'docker inspect -f "{{.NetworkSettings.Networks.bridge.IPAddress}}" web')
	dx 'cp /etc/ufw/after.rules /root/after.rules.orig && cp /etc/ufw/after6.rules /root/after6.rules.orig'
	block_text v4 "$addr" "$id" | docker exec -i "$name" bash -c 'cat >>/etc/ufw/after.rules'
	block_text v6 "$addr" "$id" | docker exec -i "$name" bash -c 'cat >>/etc/ufw/after6.rules'
	record "ufw route allow out on docker0 proto tcp to $addr port 80 comment 'darkpanel:01J00000000000000000000000 ctr 01J00000000000000000000001'"
	record "ufw route deny out on docker0 proto tcp from 203.0.113.0/24 to $addr port 80 comment 'darkpanel:01J00000000000000000000002 ctr 01J00000000000000000000003'"
	attempt 'ufw reload'
}

cleanup_block() {
	local variant fam tool
	dx "sed -i '/^# BEGIN DARKPANEL docker\$/,/^# END DARKPANEL docker\$/d' /etc/ufw/after.rules /etc/ufw/after6.rules"
	case $(dx 'iptables --version') in
	*'(nf_tables)') variant=nft ;;
	*'(legacy)') variant=legacy ;;
	*)
		echo "$0: cannot tell the iptables variant" >&2
		exit 1
		;;
	esac
	for fam in v4 v6; do
		tool=iptables
		[ "$fam" = v6 ] && tool=ip6tables
		docker exec "$name" bash -euo pipefail -c '
chains=$("$1" -t filter | sed -n "s/^:\(darkpanel-[^ ]*\|dp-b-[^ ]*\) .*/\1/p")
{
	echo "*filter"
	echo ":DOCKER-USER - [0:0]"
	echo "-A DOCKER-USER -j RETURN"
	for c in $chains; do echo "-F $c"; done
	for c in $chains; do echo "-X $c"; done
	echo COMMIT
} >"$2"' _ "$tool-$variant-save" "/root/restore-$fam.txt"
		docker exec "$name" cat "/root/restore-$fam.txt" >"$dir/restore-$fam.txt"
	done
	attempt "iptables-$variant-restore -n < /root/restore-v4.txt"
	attempt "ip6tables-$variant-restore -n < /root/restore-v6.txt"
	attempt 'ufw reload'
}

capture() {
	local f fam bin names t
	mkdir -p "$dir/files/etc/ufw" "$dir/files/etc/default" "$dir/save"
	for f in after.rules after6.rules user.rules user6.rules; do
		docker exec "$name" cat "/etc/ufw/$f" >"$dir/files/etc/ufw/$f"
	done
	docker exec "$name" cat /etc/default/ufw >"$dir/files/etc/default/ufw"
	dx 'iptables --version; ufw --version | sed -n 1p; dockerd --version' >"$dir/versions.txt"
	dx 'curl -fsS --unix-socket /var/run/docker.sock http://localhost/info | jq -S .' >"$dir/info.json"
	dx 'curl -fsS --unix-socket /var/run/docker.sock http://localhost/version | jq -S .' >"$dir/version.json"
	dx 'docker network inspect $(docker network ls -q) | jq -S "sort_by(.Name)"' >"$dir/networks.json"
	dx 'docker inspect $(docker ps -aq) | jq -S "sort_by(.Name)"' >"$dir/containers.json"
	dx 'ip -o link | awk -F": " "{print \$2}" | sed "s/@.*//" | sort' >"$dir/interfaces.txt"
	for fam in v4 v6; do
		bin=iptables names=ip_tables_names
		[ "$fam" = v6 ] && bin=ip6tables names=ip6_tables_names
		for t in filter nat raw mangle security; do
			dx "$bin-nft-save -t $t" | sed -e '/^# Generated by /d' -e '/^# Completed on /d' -e 's/^\(:.*\) \[[0-9]*:[0-9]*\]$/\1 [0:0]/' >"$dir/save/nft-$fam-$t.txt"
		done
		for t in $(dx "cat /proc/net/$names 2>/dev/null || true"); do
			dx "$bin-legacy-save -t $t" | sed -e '/^# Generated by /d' -e '/^# Completed on /d' -e 's/^\(:.*\) \[[0-9]*:[0-9]*\]$/\1 [0:0]/' >"$dir/save/legacy-$fam-$t.txt"
		done
	done
}

for scenario in base block cleanup routed; do
	dir=$outdir/$slug/$scenario
	rm -rf "$dir"
	mkdir -p "$dir"
	name=dp-w2-cap-$slug-$scenario
	docker rm -f "$name" >/dev/null 2>&1 || true
	docker run -d --privileged --name "$name" --tmpfs /var/lib/docker:exec -v "$(hostpath "$pkgs"):/debs:ro" "$image" sleep infinity >/dev/null
	dx 'timeout 900 apt-get update -qq >/dev/null'
	dx 'DEBIAN_FRONTEND=noninteractive timeout 900 apt-get install -y -qq ufw iptables nftables procps iproute2 curl ca-certificates jq >/tmp/apt.log 2>&1 || { cat /tmp/apt.log >&2; exit 1; }'
	dx 'DEBIAN_FRONTEND=noninteractive timeout 900 apt-get install -y -qq /debs/*.deb >/tmp/apt.log 2>&1 || { cat /tmp/apt.log >&2; exit 1; }'
	base
	case $scenario in
	block) block ;;
	cleanup)
		block
		cleanup_block
		;;
	routed) record 'docker network create -o com.docker.network.bridge.gateway_mode_ipv4=routed --subnet 198.51.100.0/24 routednet' ;;
	esac
	capture
	docker rm -f "$name" >/dev/null 2>&1 || true
	name=
	echo "captured $slug/$scenario"
done
